package s2

import (
	"bytes"
	"encoding/binary"
	"math/rand"
	"reflect"
	"testing"
)

func encodeShapeIndex(t *testing.T, index *ShapeIndex) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() failed: %v", err)
	}
	return buf.Bytes()
}

func roundTripShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(encodeShapeIndex(t, index))); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	return got
}

// checkShapeIndexEqual verifies that two indexes have the same shapes (by ID)
// and the same cell structure.
func checkShapeIndexEqual(t *testing.T, got, want *ShapeIndex) {
	t.Helper()
	if !got.IsFresh() {
		t.Errorf("decoded index is not fresh")
	}
	if got.Len() != want.Len() || got.nextID != want.nextID {
		t.Fatalf("got %d shapes, nextID %d; want %d, %d", got.Len(), got.nextID, want.Len(), want.nextID)
	}
	for id, ws := range want.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Fatalf("shape %d missing after decode", id)
		}
		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
			t.Errorf("shape %d: type %T, want %T", id, gs, ws)
		}
		if gs.NumEdges() != ws.NumEdges() || gs.NumChains() != ws.NumChains() ||
			gs.Dimension() != ws.Dimension() || gs.ReferencePoint() != ws.ReferencePoint() {
			t.Errorf("shape %d: properties differ after decode", id)
		}
		for e := 0; e < ws.NumEdges(); e++ {
			if gs.Edge(e) != ws.Edge(e) {
				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
			}
		}
		for c := 0; c < ws.NumChains(); c++ {
			if gs.Chain(c) != ws.Chain(c) {
				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
			}
		}
	}

	want.Build()
	if !reflect.DeepEqual(got.cells, want.cells) {
		t.Fatalf("cells = %v, want %v", got.cells, want.cells)
	}
	for _, id := range want.cells {
		if !reflect.DeepEqual(got.cellMap[id], want.cellMap[id]) {
			t.Errorf("cell %v: contents differ after decode", id)
		}
	}
}

func TestShapeIndexEncodeEmpty(t *testing.T) {
	data := encodeShapeIndex(t, NewShapeIndex())
	if len(data) == 0 {
		t.Fatal("empty index encoded to no bytes")
	}
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	if got.Len() != 0 || len(got.cells) != 0 {
		t.Errorf("decoded empty index has %d shapes, %d cells", got.Len(), len(got.cells))
	}

	// Decoding into a zero value works too.
	var zero ShapeIndex
	if err := zero.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() into zero value failed: %v", err)
	}
	zero.Add(makePolyline("0:0, 1:1"))
	if zero.NumEdges() != 1 || len(zero.Iterator().index.cells) == 0 {
		t.Errorf("index decoded into zero value is not usable")
	}
}

func allBuiltinShapes() []Shape {
	pv := PointVector(parsePoints("0:0, 1:1, 2:2"))
	return []Shape{
		makePolygon("0:0, 0:10, 10:10, 10:0; 2:2, 8:2, 8:8, 2:8", true),
		makePolygon("", false),
		makePolygon("full", false),
		makePolyline("0:0, 1:5, 3:3, 10:10"),
		makeLoop("-5:-5, -5:5, 5:5, 5:-5"),
		EmptyLoop(),
		FullLoop(),
		&pv,
		makeLaxPolyline("20:20, 21:21, 21:21, 25:20"),
		makeLaxPolygon("30:30, 30:35, 35:35; 31:31, 34:31, 34:34"),
		LaxLoopFromPoints(parsePoints("40:40, 40:45, 45:45")),
	}
}

func TestShapeIndexEncodeAllShapeTypes(t *testing.T) {
	index := NewShapeIndex()
	for _, s := range allBuiltinShapes() {
		index.Add(s)
	}
	index.Build()
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, got, index)

	// Each shape on its own, too.
	for _, s := range allBuiltinShapes() {
		index := NewShapeIndex()
		index.Add(s)
		checkShapeIndexEqual(t, roundTripShapeIndex(t, index), index)
	}

	// Polygon and Loop internals are restored exactly.
	p := got.Shape(0).(*Polygon)
	wp := index.Shape(0).(*Polygon)
	if p.hasHoles != wp.hasHoles || p.bound != wp.bound || p.numVertices != wp.numVertices ||
		p.NumLoops() != wp.NumLoops() || p.Loop(1).depth != wp.Loop(1).depth {
		t.Errorf("decoded polygon state differs")
	}
	if !p.IsValid() || !p.Contains(wp) || !wp.Contains(p) {
		t.Errorf("decoded polygon is not equivalent")
	}
	if !got.Shape(2).(*Polygon).IsFull() || !got.Shape(1).(*Polygon).IsEmpty() {
		t.Errorf("full/empty polygons not preserved")
	}
	if !got.Shape(5).(*Loop).IsEmpty() || !got.Shape(6).(*Loop).IsFull() {
		t.Errorf("full/empty loops not preserved")
	}
}

func TestShapeIndexEncodeQueriesWithoutBuild(t *testing.T) {
	index := NewShapeIndex()
	for _, s := range allBuiltinShapes() {
		index.Add(s)
	}
	// Encode without an explicit Build.
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, got, index)

	wantQ := NewContainsPointQuery(index, VertexModelSemiOpen)
	gotQ := NewContainsPointQuery(got, VertexModelSemiOpen)
	for i := 0; i < 1000; i++ {
		p := randomPoint()
		if g, w := gotQ.Contains(p), wantQ.Contains(p); g != w {
			t.Errorf("Contains(%v) = %v, want %v", p, g, w)
		}
	}
	for _, p := range parsePoints("5:5, 1:1, 32:32, 41:43, -1:-1") {
		if g, w := len(gotQ.ContainingShapes(p)), len(wantQ.ContainingShapes(p)); g != w {
			t.Errorf("ContainingShapes(%v) has %d shapes, want %d", p, g, w)
		}
	}
	quadraticValidate(t, got)
	testIteratorMethods(t, got)
}

func TestShapeIndexEncodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	shapes := allBuiltinShapes()
	for _, s := range shapes {
		index.Add(s)
	}
	index.Build()
	index.Remove(shapes[0])
	index.Remove(shapes[3])
	index.Remove(shapes[len(shapes)-1])

	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, got, index)
	if got.Shape(0) != nil || got.Shape(3) != nil {
		t.Errorf("removed shapes reappeared after decode")
	}

	// New shapes get fresh IDs and are indexed, and decoded shapes can be removed.
	pl := makePolyline("50:50, 51:51")
	if id := got.Add(pl); id != index.nextID {
		t.Errorf("Add() after decode = %d, want %d", id, index.nextID)
	}
	got.Remove(got.Shape(4))
	want := NewShapeIndex()
	for id := int32(0); id < got.nextID; id++ {
		want.shapes[id] = got.Shape(id)
	}
	want.nextID = got.nextID
	want.status = stale
	want.Build()
	got.Build()
	if !reflect.DeepEqual(got.cells, want.cells) {
		t.Errorf("incremental update after decode differs from full build")
	}
}

func TestShapeIndexEncodeZeroEdgeShapes(t *testing.T) {
	var emptyPV PointVector
	index := NewShapeIndex()
	index.Add(&emptyPV)
	index.Add(makePolyline(""))
	p1 := Polyline(parsePoints("1:1"))
	index.Add(&p1)
	index.Add(LaxPolylineFromPoints(nil))
	index.Add(LaxLoopFromPoints(nil))
	index.Add(LaxPolygonFromPoints(nil))
	index.Add(LaxPolygonFromPoints([][]Point{{}}))                                        // full
	index.Add(LaxPolygonFromPoints([][]Point{{}, parsePoints("1:1"), {}}))                // mixed chain counts
	index.Add(LaxPolygonFromPoints([][]Point{parsePoints("1:1, 2:2"), {}, parsePoints("3:3, 3:4, 4:4")}))
	index.Add(&Polygon{})
	index.Add(&Loop{})
	checkShapeIndexEqual(t, roundTripShapeIndex(t, index), index)
}

func TestShapeIndexEncodeUnsupportedShape(t *testing.T) {
	index := NewShapeIndex()
	index.Add(edgeVectorShapeFromPoints(parsePoint("0:0"), parsePoint("1:1")))
	var buf bytes.Buffer
	if err := index.Encode(&buf); err == nil {
		t.Errorf("Encode() of unsupported shape succeeded")
	}
}

func TestShapeIndexDecodeMalformed(t *testing.T) {
	index := NewShapeIndex()
	for _, s := range allBuiltinShapes() {
		index.Add(s)
	}
	data := encodeShapeIndex(t, index)

	if err := NewShapeIndex().Decode(bytes.NewReader(nil)); err == nil {
		t.Errorf("Decode(empty) succeeded")
	}
	for n := 0; n < len(data); n++ {
		if err := NewShapeIndex().Decode(bytes.NewReader(data[:n])); err == nil {
			t.Fatalf("Decode() of data truncated to %d bytes succeeded", n)
		}
	}
	for i := range data {
		corrupt := append([]byte(nil), data...)
		corrupt[i] ^= 0x5a
		if err := NewShapeIndex().Decode(bytes.NewReader(corrupt)); err == nil {
			t.Fatalf("Decode() of data with byte %d corrupted succeeded", i)
		}
	}

	// A failed decode leaves the index unchanged.
	dst := NewShapeIndex()
	dst.Add(makePolyline("0:0, 1:1"))
	if err := dst.Decode(bytes.NewReader(data[:len(data)/2])); err == nil || dst.Len() != 1 {
		t.Errorf("failed Decode() modified the index")
	}

	rng := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		garbage := make([]byte, rng.Intn(200))
		rng.Read(garbage)
		if i%2 == 0 && len(garbage) >= 5 {
			copy(garbage, data[:5]) // valid header
		}
		_ = NewShapeIndex().Decode(bytes.NewReader(garbage))
	}
}

func TestShapeIndexDecodeOversizedCounts(t *testing.T) {
	header := func() []byte {
		b := binary.LittleEndian.AppendUint32(nil, shapeIndexEncodingMagic)
		return append(b, shapeIndexEncodingVersion)
	}
	huge := uint64(1) << 62
	tests := map[string][]byte{
		"maxEdgesPerCell": binary.AppendUvarint(header(), huge),
		"nextID":          binary.AppendUvarint(binary.AppendUvarint(header(), 10), huge),
		"numShapes":       binary.AppendUvarint(binary.AppendUvarint(binary.AppendUvarint(header(), 10), 100), huge),
		"numCells": binary.AppendUvarint(
			binary.AppendUvarint(binary.AppendUvarint(binary.AppendUvarint(header(), 10), 0), 0), huge),
		"numVertices": binary.AppendUvarint(append(binary.AppendUvarint(
			binary.AppendUvarint(binary.AppendUvarint(binary.AppendUvarint(header(), 10), 1), 1), 0),
			byte(shapeKindPolyline)), huge),
		"numLoops": binary.AppendUvarint(append(binary.AppendUvarint(
			binary.AppendUvarint(binary.AppendUvarint(binary.AppendUvarint(header(), 10), 1), 1), 0),
			byte(shapeKindLaxPolygon)), huge),
	}
	for name, data := range tests {
		if err := NewShapeIndex().Decode(bytes.NewReader(data)); err == nil {
			t.Errorf("%s: Decode() with oversized count succeeded", name)
		}
	}
}

