}

func TestShapeIndexEncodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	shapes := allBuiltinShapes()
	for _, s := range shapes {
		index.Add(s)
	}
	index.Build()
	index.Remove(shapes[0])
	index.Remove(shapes[3])
	index.Remove(shapes[len(shapes)-1])

	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, got, index)
	if got.Shape(0) != nil || got.Shape(3) != nil {
		t.Errorf("removed shapes reappeared after decode")
	}

	// New shapes get fresh IDs and are indexed, and decoded shapes can be removed.
	pl := makePolyline("50:50, 51:51")
	if id := got.Add(pl); id != index.nextID {
		t.Errorf("Add() after decode = %d, want %d", id, index.nextID)
	}
	got.Remove(got.Shape(4))
	want := NewShapeIndex()
	for id := int32(0); id < got.nextID; id++ {
		want.shapes[id] = got.Shape(id)
	}
	want.nextID = got.nextID
	want.status = stale
	want.Build()
	got.Build()
	if !reflect.DeepEqual(got.cells, want.cells) {
		t.Errorf("incremental update after decode differs from full build")
	}
}

